import os
import glob
import pandas as pd
import numpy as np
from xgboost import XGBClassifier

def load_latest_file(pattern):
    files = glob.glob(pattern)
    return max(files, key=os.path.getctime) if files else None

def load_categories():
    """Loads all categorized stock lists generated by dynamic_classifier.py."""
    categories = {}
    
    safe_file = load_latest_file("../data/categorized/safe/safe_*.csv")
    obs_file = load_latest_file("../data/categorized/observation/obs_*.csv")
    gorengan_file = load_latest_file("../data/categorized/gorengan/gorengan_*.csv")

    if safe_file:
        df_safe = pd.read_csv(safe_file)
        if 'ticker' in df_safe.columns:
            for t in df_safe['ticker']:
                categories[t] = "Safe & Recommended 🟢"

    if obs_file:
        df_obs = pd.read_csv(obs_file)
        if 'ticker' in df_obs.columns:
            for t in df_obs['ticker']:
                categories[t] = "Need Observation 🟡"

    if gorengan_file:
        df_gor = pd.read_csv(gorengan_file)
        if 'ticker' in df_gor.columns:
            for t in df_gor['ticker']:
                categories[t] = "Gorengan / High Risk 🔴"

    return categories

def explain_signal(row, prob, category):
    """Generates a human-readable XAI breakdown for sentiment, chart, and risk tier."""
    reasons = []

    rsi = row.get('RSI', 50)
    close = row.get('close', 0)
    sma = row.get('SMA_20', close)
    sentiment = row.get('Sentiment_Score', 0.0)
    atr = row.get('ATR', 0)

    # 1. Market Category & Liquidity Context
    reasons.append(f"🏷️ Market Tier: {category}")

    # 2. Technical Chart Explanations
    if rsi < 35:
        reasons.append(f"🟢 Oversold RSI ({rsi:.1f}) indicating potential bullish reversal")
    elif rsi > 65:
        reasons.append(f"🔴 Overbought RSI ({rsi:.1f}) signaling short-term pullback risk")
    else:
        reasons.append(f"🟡 Neutral RSI momentum ({rsi:.1f})")

    # 3. Moving Average Trend Alignment
    if close > sma:
        dist = ((close - sma) / sma) * 100
        reasons.append(f"📈 Price is trading +{dist:.1f}% above 20-period SMA (Upward Trend)")
    else:
        dist = ((sma - close) / sma) * 100
        reasons.append(f"📉 Price is trading -{dist:.1f}% below 20-period SMA (Downward Trend)")

    # 4. News & Sentiment Explanations
    if sentiment > 0.15:
        reasons.append(f"📰 Strong Positive News Sentiment Score (+{sentiment:.2f})")
    elif sentiment < -0.15:
        reasons.append(f"📰 Negative News Sentiment Score ({sentiment:.2f})")
    else:
        reasons.append(f"📰 Neutral/Baseline News Sentiment ({sentiment:.2f})")

    # 5. Volatility Context
    atr_pct = (atr / close) * 100 if close > 0 else 0
    reasons.append(f"⚡ Market Volatility (ATR): Rp {atr:,.2f} ({atr_pct:.1f}% price range)")

    return reasons

def run_xai_pipeline():
    # 1. Load Technical & Sentiment Data
    tech_file = load_latest_file("../data/technical/technical_*.csv")
    if not tech_file:
        print("❌ Technical dataset not found in ../data/technical/")
        return

    df = pd.read_csv(tech_file)

    # 2. Load Market Categories
    category_map = load_categories()

    # 3. Load Trained Model Artifact
    model_path = "../models/xgb_idx_sentiment_aware.json"
    if not os.path.exists(model_path):
        model_path = "../models/xgb_idx_model.json"

    if not os.path.exists(model_path):
        print("❌ Trained model not found. Run train_multi_horizon.py first!")
        return

    model = XGBClassifier()
    model.load_model(model_path)

    # 4. Feature Vector Setup
    feature_cols = ['RSI', 'ATR', 'SMA_20', 'close', 'volume']
    if 'Sentiment_Score' not in df.columns:
        df['Sentiment_Score'] = 0.0
    feature_cols.append('Sentiment_Score')

    valid_df = df.dropna(subset=feature_cols).copy()
    if 'Ticker' in valid_df.columns:
        valid_df = valid_df.groupby('Ticker').last().reset_index()

    if valid_df.empty:
        print("⚠️ No valid rows for XAI inference.")
        return

    # Run Prediction
    X_live = valid_df[feature_cols]
    valid_df['Up_Probability'] = model.predict_proba(X_live)[:, 1]

    print("\n=======================================================================")
    print("      🧠 EXPLAINABLE AI (XAI) IDX TRADING & SENTIMENT REPORT           ")
    print("=======================================================================")

    for idx, row in valid_df.iterrows():
        ticker = row.get('Ticker', 'UNKNOWN')
        price = row['close']
        atr = row['ATR']
        prob = row['Up_Probability']

        if ticker in ["^JKSE", "CL=F", "GC=F"]:
            continue

        category = category_map.get(ticker, "Unclassified / Need Observation 🟡")

        # Safety Override: Automatically block Saham Gorengan from receiving BUY signals
        if "Gorengan" in category:
            signal = "BLOCKED 🔴 (High Risk / Saham Gorengan)"
            sl = tp = 0.0
        elif prob >= 0.60:
            signal = "BUY 🟢"
            sl = price - (1.5 * atr)
            tp = price + (3.0 * atr)
        elif prob <= 0.40:
            signal = "SELL 🔴"
            sl = tp = 0.0
        else:
            signal = "HOLD 🟡"
            sl = tp = 0.0

        explanations = explain_signal(row, prob, category)

        print(f"\nTicker         : {ticker}")
        print(f" Current Price : Rp {price:,.2f}")
        print(f" Signal        : {signal}")
        print(f" AI Confidence : {prob * 100:.1f}%")
        if sl > 0:
            print(f" Risk Bounds   : Stop-Loss Rp {sl:,.2f} | Take-Profit Rp {tp:,.2f}")
        
        print(" 🔍 XAI Reasoning Breakdown:")
        for reason in explanations:
            print(f"    • {reason}")

    print("\n=======================================================================\n")

if __name__ == "__main__":
    run_xai_pipeline()
